// The game's globals are obfuscated with random look-alike names that change with every
// game version. They come from desktop/dev/names.js (globalThis.PB2_NAMES), generated by
// "npm run find-names". Only the modules in game/ use these keys.

export const N = globalThis.PB2_NAMES || {};
// Sad Burst 2 (desktop/clients.js): its names file says so in its version.
export const SADBURST = String(N.version || '').startsWith('sadburst-');
export const CLIENT_TITLE = SADBURST ? 'Sad Burst 2' : 'Plazma Burst 2';
export const FIND_NAMES = SADBURST ? 'npm run find-names -- --sadburst' : 'npm run find-names';
export const namesMissing = globalThis.PB2_NAMES
  ? Object.keys(N).filter((k) => !N[k])
  : ['(names.js not loaded)'];

export function nameOf(key) {
  const name = N[key];
  // Missing: not found in this game version, or names.js is older than the console.
  if (!name) throw new Error(`game name "${key}" is not in ${SADBURST ? 'desktop/dev/names.sadburst.js' : 'desktop/dev/names.js'}. Run "${FIND_NAMES}", then restart the app.`);
  return name;
}

// Compiled once per name. Indirect eval runs in global scope, so it also reaches the
// game's top-level let/const variables, which are not properties of globalThis.
const getters = new Map();
const setters = new Map();

export function read(key) {
  let f = getters.get(key);
  if (!f) {
    const n = nameOf(key);
    f = (0, eval)(`(() => typeof ${n} === 'undefined' ? undefined : ${n})`);
    getters.set(key, f);
  }
  return f();
}

export function write(key, v) {
  let f = setters.get(key);
  if (!f) {
    f = (0, eval)(`((v) => { ${nameOf(key)} = v; })`);
    setters.set(key, f);
  }
  f(v);
}

export const call = (key, ...args) => read(key)(...args);

// \u-escaped form of a name, for help texts the user can type.
export const escName = (key) => String(N[key] || `<${key}>`)
  .replace(/[^\x00-\x7f]/g, (c) => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
